&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_laccident_qui_attendait_de_se_produire&quot;&gt;L&amp;#8217;Accident qui Attendait de se Produire&lt;/a&gt;
