&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Suppression SupabaseManager + ContactFormHandler + init bloc&lt;/p&gt;&lt;/td&gt;
