  card &quot;P4 — Cycle de vie\n(133 lignes)&quot; as D2
  card &quot;P9 — Références\n(30 lignes)&quot; as D3
}

rectangle &quot;🔴 **Jamais consulté**\n215 lignes (34%)&quot; as JAM #FFCDD2 {
  card &quot;P5 — Métriques\n(49 lignes)&quot; as J1
  card &quot;P6 — Détection\n(72 lignes)&quot; as J2
  card &quot;P7 — Amélioration\n(39 lignes)&quot; as J3
  card &quot;P8 — Bootstrap\n(13 lignes)&quot; as J4
  card &quot;Annexes — Glossaire\n(42 lignes)&quot; as J5
}

rectangle &quot;🟢 **Connaissance unique**\n161 lignes (26%)&quot; as UNI #C8E6C9 {
  card &quot;P1 — Vue d&#39;ensemble\n(64 lignes)&quot; as U1
  card &quot;P2 — Structure fichiers\n(97 lignes)&quot; as U2
}

