&lt;li&gt;&lt;a href=&quot;#_rendu_en_ligne&quot;&gt;Rendu en ligne&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_le_diagnostic_serve_ne_pointait_pas_vers_le_bon_dossier&quot;&gt;Le diagnostic : &lt;code&gt;serve&lt;/code&gt; ne pointait pas vers le bon dossier&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_la_cause_racine_jbake_cli_ne_fonctionne_pas_comme_ça&quot;&gt;La cause racine : JBake CLI ne fonctionne pas comme ça&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_la_solution_arguments_positionnels_pas_des_flags&quot;&gt;La solution : arguments positionnels, pas des flags&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_vérification_rapide_avec_curl&quot;&gt;Vérification rapide avec curl&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_pourquoi_ce_bug_était_vicieux&quot;&gt;Pourquoi ce bug était vicieux&lt;/a&gt;&lt;/li&gt;
