&lt;li&gt;&lt;a href=&quot;#_projectstructuur&quot;&gt;Projectstructuur&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_configuratie_van_het_pakket_met_pyproject_toml&quot;&gt;Configuratie van het pakket met pyproject.toml&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_workflow_cicd_tests_en_kwaliteit&quot;&gt;Workflow CI/CD - Tests en kwaliteit&lt;/a&gt;&lt;/li&gt;
