&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dit bericht beschrijft het volledige ontwerpproces en testen (TDD) van een Gradle-plugin geschreven in Kotlin DSL. Dit plugin automatiseert de generatie van statische sites met &lt;strong&gt;JBake&lt;/strong&gt; en de &lt;strong&gt;Git-implementatie&lt;/strong&gt; via &lt;strong&gt;JGit&lt;/strong&gt;, allemaal vanaf een YAML-configuratiebestand.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_doel&quot;&gt;doel&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Een Gradle-plugin maken:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;configureerbaar in Kotlin DSL;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;in staat om&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;genereer een statische site vanuit JBake ;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;implementeren op een externe Git-opslagplaats via JGit ;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;integreerbaar in een CI/CD-workflow;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;getest volgens een TDD-aanpak.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_declaratieve_configuratie&quot;&gt;Declaratieve configuratie&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hier is een voorbeeld van een YAML-configuratie om te modelleren in onze DSL :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/trainings.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Deze configuratie wordt weergegeven via een declareerbare Gradle-extensie in Kotlin DSL.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_architectuur_van_de_plugin&quot;&gt;Architectuur van de plugin&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
package &quot;engine-plugin&quot; {
class WorkspaceEngineExtension
class GenerateSiteTask
interface GitAdapter
class JGitAdapter
WorkspaceEnginePlugin --&amp;gt; WorkspaceEngineExtension
WorkspaceEnginePlugin --&amp;gt; GenerateSiteTask
GenerateSiteTask --&amp;gt; GitAdapter
JGitAdapter ..|&amp;gt; GitAdapter
}
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_definitie_van_de_dsl_extensie&quot;&gt;Definitie van de DSL-extensie&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;open class WorkspaceEngineExtension {
    var outputDir: String = &quot;build/site&quot;
    var template: String = &quot;freemarker&quot;
    var repoUrl: String = &quot;&quot;
    var branch: String = &quot;main&quot;
    var message: String = &quot;Generated by engine&quot;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_definitie_van_de_aangepaste_taak&quot;&gt;Definitie van de aangepaste taak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;abstract class GenerateSiteTask : DefaultTask() {
    lateinit var gitAdapter: GitAdapter

    @get:Input abstract val repoUrl: Property&amp;lt;String&amp;gt;
    @get:InputDirectory abstract val outputDir: DirectoryProperty
    @get:Input abstract val branch: Property&amp;lt;String&amp;gt;
    @get:Input abstract val message: Property&amp;lt;String&amp;gt;

    @TaskAction
    fun run() {
        val repo = gitAdapter.cloneRepository(repoUrl.get(), outputDir.get().asFile)
        gitAdapter.commitAndPush(repo, branch.get(), message.get())
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_interface_gitadapter&quot;&gt;Interface GitAdapter&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;interface GitAdapter {
    fun cloneRepository(uri: String, directory: File): Repository
    fun commitAndPush(repo: Repository, branch: String, message: String)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_concrete_implementatie_met_jgit&quot;&gt;Concrete implementatie met JGit&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class JGitAdapter : GitAdapter {
    override fun cloneRepository(uri: String, directory: File): Repository {
        return Git.cloneRepository()
            .setURI(uri)
            .setDirectory(directory)
            .call()
            .repository
    }

    override fun commitAndPush(repo: Repository, branch: String, message: String) {
        Git(repo).use {
            it.add().addFilepattern(&quot;.&quot;).call()
            it.commit().setMessage(message).call()
            it.push().call()
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_configuratie_dsl_kotlin&quot;&gt;Configuratie DSL Kotlin&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;workspaceEngine {
    outputDir = &quot;build/out&quot;
    template = &quot;freemarker&quot;
    repoUrl = &quot;https://github.com/cheroliv/trainings.git&quot;
    branch = &quot;main&quot;
    message = &quot;deploy from plugin&quot;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_eenheidstests_met_mockito&quot;&gt;Eenheidstests met Mockito&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_afhankelijkheden&quot;&gt;Afhankelijkheden&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;testImplementation(&quot;org.mockito:mockito-core:5.12.0&quot;)
testImplementation(&quot;org.mockito.kotlin:mockito-kotlin:5.2.1&quot;)
testImplementation(&quot;org.junit.jupiter:junit-jupiter:5.10.0&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_test_van_het_gedrag_van_git&quot;&gt;Test van het gedrag van Git&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class GenerateSiteTaskMockitoTest {

    @TempDir
    lateinit var tempDir: File

    @Test
    fun `task should call clone and commitAndPush`() {
        val project = ProjectBuilder.builder().build()
        val task = project.tasks.create(&quot;generateSite&quot;, GenerateSiteTask::class.java)

        val mockGitAdapter = mock&amp;lt;GitAdapter&amp;gt;()
        val mockRepo = mock&amp;lt;Repository&amp;gt;()

        whenever(mockGitAdapter.cloneRepository(any(), any())).thenReturn(mockRepo)

        task.gitAdapter = mockGitAdapter
        task.repoUrl.set(&quot;https://github.com/cheroliv/test.git&quot;)
        task.outputDir.set(project.layout.projectDirectory.dir(tempDir.name))
        task.branch.set(&quot;main&quot;)
        task.message.set(&quot;test commit&quot;)

        task.run()

        verify(mockGitAdapter).cloneRepository(eq(&quot;https://github.com/cheroliv/test.git&quot;), any())
        verify(mockGitAdapter).commitAndPush(eq(mockRepo), eq(&quot;main&quot;), eq(&quot;test commit&quot;))
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor &quot;Ontwikkelaar&quot; as Dev
participant &quot;Gradle ProjectBuilder&quot; as Project
participant &quot;GenereerSiteTaak&quot; as Task
participant &quot;GitAdapter (Mock)&quot; as Adapter
participant &quot;JGitAdapter / Mockito&quot; as Impl

Dev -&amp;gt; Project : construit projet Gradle
Dev -&amp;gt; Task : configure les propriétés
Task -&amp;gt; Adapter : cloneRepository()
Adapter -&amp;gt; Impl : simulé par Mockito
Task -&amp;gt; Adapter : commitAndPush()
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_conclusie&quot;&gt;Conclusie&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Scheiding van verantwoordelijkheden via`GitAdapter`Hiermee kan TDD volledig worden toegepast bij de ontwikkeling van Gradle-plugins :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;De Git-aanroepen zijn geabstraheerd en testbaar;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;De DSL-configuratie is netjes en overzichtelijk;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;het plugin blijft agnostisch ten opzichte van de werkelijke implementatie&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Deze aanpak garandeert een hoge testbaarheid en uitbreidbaarheid (naar GitHub API, GitLab, enz.).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_volgende_stappen&quot;&gt;Volgende stappen&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;De JBake-generatie integreren als een`BakeAdapter`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Voeg integratietests toe met`GradleRunner`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ondersteun het automatisch laden van bestanden`site.yml`via SnakeYAML&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_inleiding&quot;&gt;Inleiding&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_wat_is_asciidoc&quot;&gt;Wat is AsciiDoc?&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_waarom_asciidoc_kiezen&quot;&gt;Waarom AsciiDoc kiezen?&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_use_case_diagram_use_case&quot;&gt;use-case diagram (Use Case)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_mindmap_diagram&quot;&gt;Mindmap diagram&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_stroomdiagram&quot;&gt;stroomdiagram&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_basisstructuur_van_een_asciidoc_bestand&quot;&gt;Basisstructuur van een AsciiDoc-bestand&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_basisyntaxis&quot;&gt;basisyntaxis&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_titels_en_secties&quot;&gt;Titels en secties&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_vet_cursief_en_monospaced_tekst&quot;&gt;Vet, cursief en monospaced tekst&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_opsommingspunten_en_genummerde_lijsten&quot;&gt;Opsommingspunten en genummerde lijsten&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_links_en_afbeeldingen&quot;&gt;Links en afbeeldingen&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_codeblokken&quot;&gt;Codeblokken&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tabellen&quot;&gt;Tabellen&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_notities_en_waarschuwingen&quot;&gt;Notities en waarschuwingen&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_gebruik_van_attributen_en_variabelen&quot;&gt;Gebruik van attributen en variabelen&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_veelvoorkomende_gebruiksscenarios&quot;&gt;Veelvoorkomende gebruiksscenario&amp;#8217;s&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_beste_praktijken&quot;&gt;Beste praktijken&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_conclusie&quot;&gt;Conclusie&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_verder_gaan&quot;&gt;Verder gaan&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_inleiding&quot;&gt;Inleiding&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Doelgroep :&lt;/em&gt; Ontwikkelaars, technische schrijvers, en iedereen die technische documentatie of rijke artikelen wil schrijven.&lt;/div&gt;
&lt;p&gt;AsciiDoc is een lichtgewicht opmaaktaal, ontworpen om gestructureerde technische documenten, artikelen, boeken of presentaties te schrijven. Het onderscheidt zich door de leesbaarheid, de syntactische rijkdom en het vermogen om verschillende formaten te genereren (HTML, PDF, DocBook, enzovoort). In dit artikel gaan we de essentiële syntaxis van AsciiDoc onderzoeken en tips geven voor een snelle kennismaking.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_wat_is_asciidoc&quot;&gt;Wat is AsciiDoc?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AsciiDoc is een taal voor documentbeschrijving, vergelijkbaar met Markdown maar krachtiger. Het maakt het efficiënt mogelijk om teksten, titels, lijsten, tabellen, codeblokken en veel meer te structureren. De veelzijdigheid maakt het een populaire keuze voor de documentatie van open source-projecten, het schrijven van boeken en webpublicatie.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_waarom_asciidoc_kiezen&quot;&gt;Waarom AsciiDoc kiezen?&lt;/h3&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Leesbare en intuïtieve syntaxis.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Native ondersteuning van complexe structuren (tabellen, notities, admonities, etc.)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Multi-formaatgeneratie (HTML, PDF, ePub, DocBook…)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Eenvoudige integratie met statische sitegeneratoren zoals JBake of Antora.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Geavanceerde aanpassing met attributen en extensies.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_use_case_diagram_use_case&quot;&gt;use-case diagram (Use Case)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Een gebruikscase-diagram toont de belangrijkste interacties tussen gebruikers en het systeem. Hier is een eenvoudig voorbeeld voor een documentatiesysteem:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
:Utilisateur: --&amp;gt; (Rédiger documentation)
:Utilisateur: --&amp;gt; (Générer PDF)
:Utilisateur: --&amp;gt; (Publier sur site web)
(Rédiger documentation) ..&amp;gt; (Générer PDF) : inclut
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_mindmap_diagram&quot;&gt;Mindmap diagram&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;De mind map (mentale kaart) is ideaal om de concepten die gerelateerd zijn aan AsciiDoc en hun relaties te verkennen:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
* AsciiDoc
** Syntaxe
*** Titres
*** Listes
*** Blocs de code
*** Tableaux
** Extensions
*** PlantUML
*** MathJax
** Export
*** HTML
*** PDF
*** EPUB
@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_stroomdiagram&quot;&gt;stroomdiagram&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Een flowdiagram maakt het mogelijk om het proces van genereren van een AsciiDoc-document te beschrijven:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Écrire fichier .adoc;
:Ajouter images et diagrammes;
if (Valider la syntaxe ?) then (oui)
:Générer HTML/PDF;
:Publier ou partager;
else (non)
:Corriger erreurs;
:back to start;
endif
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_basisstructuur_van_een_asciidoc_bestand&quot;&gt;Basisstructuur van een AsciiDoc-bestand&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Een AsciiDoc-bestand begint meestal met een titel, optionele attributen, gevolgd door gestructureerde inhoud. Hier is een minimalistisch voorbeeld:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Titre Principal
Auteur
2024-09-03
:toc:
:icons: font

Votre contenu commence ici...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_basisyntaxis&quot;&gt;basisyntaxis&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_titels_en_secties&quot;&gt;Titels en secties&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AsciiDoc ondersteunt meerdere niveaus van titels:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Titre de niveau 1
== Titre de niveau 2
=== Titre de niveau 3
==== Titre de niveau 4&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_vet_cursief_en_monospaced_tekst&quot;&gt;Vet, cursief en monospaced tekst&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;*gras* _italique_ `monospace`&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_opsommingspunten_en_genummerde_lijsten&quot;&gt;Opsommingspunten en genummerde lijsten&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* Élément 1
* Élément 2

. Premier
. Deuxième
. Troisième&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_links_en_afbeeldingen&quot;&gt;Links en afbeeldingen&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;Lien standard : https://asciidoc.org[AsciiDoc]
Image : image::images/logo.png[AsciiDoc Logo]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_codeblokken&quot;&gt;Codeblokken&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;[source,python]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;def hello(): print(&quot;Bonjour AsciiDoc !&quot;)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tabellen&quot;&gt;Tabellen&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;|===
| Colonne 1 | Colonne 2

| Valeur A
| Valeur B

| Valeur C
| Valeur D
|===&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_notities_en_waarschuwingen&quot;&gt;Notities en waarschuwingen&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AsciiDoc biedt visuele informatieblokken :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;NOTE: Ceci est une note importante.
TIP: Conseil utile pour l’utilisateur.
WARNING: Attention à ce point.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_gebruik_van_attributen_en_variabelen&quot;&gt;Gebruik van attributen en variabelen&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Aangepaste attributen maken het mogelijk om waarden opnieuw te gebruiken of gedrag te configureren :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:project-name: AsciiDoc Explorer

Le projet s’appelle {project-name}.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_veelvoorkomende_gebruiksscenarios&quot;&gt;Veelvoorkomende gebruiksscenario&amp;#8217;s&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Documentatie open source project (README, technische handleidingen) - Schrijven van boeken en e-boeken - Automatische generatie van statische websites (JBake, Antora) - Technische presentaties&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_beste_praktijken&quot;&gt;Beste praktijken&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Gebruik consistente titels en een automatisch gegenereerde inhoudsopgave (:toc:). - Geef de voorkeur aan waarschuwingen om de aandacht te vestigen op belangrijke punten. - Structureer je bestanden om het onderhoud te faciliteren. Maak gebruik van de gemarkeerde codeblokken om voorbeelden te illustreren.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_conclusie&quot;&gt;Conclusie&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AsciiDoc is een krachtig en toegankelijk hulpmiddel voor het schrijven van elke technische documentatie of gestructureerd artikel. De rijke syntaxis, gecombineerd met multi-formaatgeneratie, maakt het een waardevolle bondgenoot voor veeleisende ontwikkelaars en schrijvers. Probeer AsciiDoc in uw volgende project uit en ontdek het verschil!&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_verder_gaan&quot;&gt;Verder gaan&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Officiële documentatie : &lt;a href=&quot;https://asciidoc.org&quot; class=&quot;bare&quot;&gt;https://asciidoc.org&lt;/a&gt; - Asciidoctor: &lt;a href=&quot;https://asciidoctor.org&quot; class=&quot;bare&quot;&gt;https://asciidoctor.org&lt;/a&gt; - JBake en AsciiDoc: &lt;a href=&quot;https://jbake.org/docs/2.6.4/#asciidoc_support&quot; class=&quot;bare&quot;&gt;https://jbake.org/docs/2.6.4/#asciidoc_support&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Deel je ervaringen en tips in een reactie!&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_het_probleem_nat_en_privéadressen&quot;&gt;Het probleem: NAT en privéadressen&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_stap_1_identificeer_uw_publiek_ip_adres&quot;&gt;Stap 1: Identificeer uw publiek IP-adres&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_stap_2_het_lokale_ip_adres_van_uw_ubuntu_machine_kennen&quot;&gt;Stap 2: Het lokale IP-adres van uw Ubuntu-machine kennen&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_stap_3_poortforwarding_configureren_op_uw_box&quot;&gt;Stap 3: Poortforwarding configureren op uw box&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_toegang_tot_de_beheerinterface&quot;&gt;Toegang tot de beheerinterface&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_instelling_van_de_omleiding&quot;&gt;Instelling van de omleiding&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_stap_4_configuratie_van_de_service_op_ubuntu&quot;&gt;Stap 4 : Configuratie van de service op Ubuntu&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_stap_5_configuratie_van_de_ubuntu_firewall&quot;&gt;Stap 5: Configuratie van de Ubuntu-firewall&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_stap_6_test_en_validatie&quot;&gt;Stap 6: Test en validatie&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_test_vanaf_het_lokale_netwerk&quot;&gt;Test vanaf het lokale netwerk&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_test_van_buitenaf&quot;&gt;Test van buitenaf&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_goede_praktijken_en_veiligheid&quot;&gt;Goede praktijken en veiligheid&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_basisbeveiliging&quot;&gt;basisbeveiliging&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_monitoring_van_verbindingen&quot;&gt;Monitoring van verbindingen&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_gebruik_van_een_reverse_proxy&quot;&gt;Gebruik van een reverse proxy&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_alternatieven_voor_poortforwarding&quot;&gt;Alternatieven voor poortforwarding&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_cloudoplossingen&quot;&gt;cloudoplossingen&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_vps_en_reverse_proxy&quot;&gt;VPS en reverse proxy&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_probleemoplossing&quot;&gt;Probleemoplossing&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_algemene_problemen&quot;&gt;Algemene problemen&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_netwerkdebug&quot;&gt;netwerkdebug&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_conclusie&quot;&gt;Conclusie&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Doelgroep: Gemiddeld&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Veronderstelde voorkennis&lt;/strong&gt; : basiskennis van Ubuntu, de terminal, basis netwerkconcepten&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Technische concepten&lt;/strong&gt; : NAT, poortdoorsturen, firewall, omgekeerde proxy&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Systeemopdrachten&lt;/strong&gt; : gebruik van de terminal, netwerkconfiguratie&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Geavanceerde secties&lt;/strong&gt; : monitoring, beveiliging, cloudalternatieven&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_het_probleem_nat_en_privéadressen&quot;&gt;Het probleem: NAT en privéadressen&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Probleemstelling: U ontwikkelt een webapplicatie op uw Ubuntu-machine en wilt deze toegankelijk maken buiten uw thuisnetwerk? U bent op de juiste plaats! In dit artikel laten we zien hoe u een lokale dienst (bijvoorbeeld op poort 8080) naar het internet kunt blootstellen door poortdoorsturing in te stellen op uw internetbox.&lt;/div&gt;
&lt;p&gt;Standaard gebruikt uw internetbox NAT (Network Address Translation) om één publiek IP-adres te delen tussen alle apparaten in uw thuisnetwerk. Uw lokale machines gebruiken privé-IP-adressen (192.168.x.x, 10.x.x.x, enz.) die niet routeerbaar zijn op het internet.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Wanneer je een service start op je Ubuntu‑machine (bijvoorbeeld een webserver op poort 8080), is deze alleen toegankelijk vanaf je lokale netwerk. Om het bereikbaar te maken vanuit Internet, moeten we een poortomleiding configureren.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_stap_1_identificeer_uw_publiek_ip_adres&quot;&gt;Stap 1: Identificeer uw publiek IP-adres&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Eerst, laten we het publieke IP-adres van uw internetverbinding ophalen:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Plusieurs méthodes au choix
curl ifconfig.me
curl ipecho.net/plain
wget -qO- http://ipecho.net/plain

# Ou encore
curl -s checkip.amazonaws.com&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dit IP-adres is het adres dat internetgebruikers zullen gebruiken om toegang te krijgen tot uw dienst.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_stap_2_het_lokale_ip_adres_van_uw_ubuntu_machine_kennen&quot;&gt;Stap 2: Het lokale IP-adres van uw Ubuntu-machine kennen&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Uw Ubuntu-machine heeft een privé IP-adres op uw lokale netwerk. Om dit te weten te komen:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Afficher toutes les interfaces réseau
ip addr show

# Ou plus spécifiquement pour l&#39;interface principale
ip route get 1.1.1.1 | awk &#39;{print $7; exit}&#39;

# Alternative avec hostname
hostname -I | awk &#39;{print $1}&#39;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Noteer dit adres (bijvoorbeeld`192.168.1.100`We zullen het nodig hebben voor de configuratie.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_stap_3_poortforwarding_configureren_op_uw_box&quot;&gt;Stap 3: Poortforwarding configureren op uw box&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;De configuratie varieert afhankelijk van het model van uw box, maar het principe blijft hetzelfde:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_toegang_tot_de_beheerinterface&quot;&gt;Toegang tot de beheerinterface&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Open uw webbrowser en ga naar de webinterface van uw box :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Freebox&lt;/strong&gt;:`192.168.1.1` ou &lt;code&gt;mafreebox.freebox.fr&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Livebox Orange&lt;/strong&gt;:`192.168.1.1`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SFR Box&lt;/strong&gt;:`192.168.1.1`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Bbox Bouygues&lt;/strong&gt;:`192.168.1.254`&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_instelling_van_de_omleiding&quot;&gt;Instelling van de omleiding&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Zoek de sectie gewijd aan poortdoorsturing (de namen variëren) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Poortdoorsturing&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;NAT/PAT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Poortdoorsturen&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Spelservers&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Maak een nieuwe regel met deze paramètres :&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;col style=&quot;width: 75%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;veld&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;waarde&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Naam/Beschrijving&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Service Web Ubuntu&quot; (of een andere expliciete naam)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Externe poort (of openbare poort)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;8080&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Interne IP-adres&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Het IP van je Ubuntu-machine (bijv. 192.168.1.100)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;interne poort (of privé poort)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;8080&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Protocol&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;TCP&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;staat&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;geactiveerd&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_stap_4_configuratie_van_de_service_op_ubuntu&quot;&gt;Stap 4 : Configuratie van de service op Ubuntu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Zorg ervoor dat uw service luistert op alle interfaces, niet alleen op localhost :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# ✅ Correct : écoute sur toutes les interfaces
python3 -m http.server 8080 --bind 0.0.0.0

# ❌ Incorrect : écoute seulement en local
python3 -m http.server 8080 --bind 127.0.0.1&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Om te controleren of uw service correct luistert:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Vérifier les ports en écoute
sudo netstat -tlnp | grep :8080
# ou avec ss (plus moderne)
sudo ss -tlnp | grep :8080&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Je zou iets moeten zien zoals`0.0.0.0:8080`en niet`127.0.0.1:8080`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_stap_5_configuratie_van_de_ubuntu_firewall&quot;&gt;Stap 5: Configuratie van de Ubuntu-firewall&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ubuntu maakt standaard gebruik van UFW (Uncomplicated Firewall). Controleer de status en open de poort indien nodig :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Vérifier le statut du pare-feu
sudo ufw status

# Si le pare-feu est actif, autoriser le port 8080
sudo ufw allow 8080/tcp

# Ou plus spécifiquement pour un service web
sudo ufw allow &#39;Apache&#39;  # si vous utilisez Apache
sudo ufw allow &#39;Nginx Full&#39;  # si vous utilisez Nginx&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_stap_6_test_en_validatie&quot;&gt;Stap 6: Test en validatie&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_test_vanaf_het_lokale_netwerk&quot;&gt;Test vanaf het lokale netwerk&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Eerst, test de toegang vanaf een andere machine in uw lokale netwerk:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Remplacez par l&#39;IP locale de votre machine Ubuntu
curl http://192.168.1.100:8080&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_test_van_buitenaf&quot;&gt;Test van buitenaf&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Nu test vanaf internet met uw publieke IP-adres:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Remplacez par votre IP publique
curl http://VOTRE_IP_PUBLIQUE:8080&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U kunt ook online tools gebruiken:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://www.yougetsignal.com/tools/open-ports/&quot; class=&quot;bare&quot;&gt;https://www.yougetsignal.com/tools/open-ports/&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://canyouseeme.org/&quot; class=&quot;bare&quot;&gt;https://canyouseeme.org/&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_goede_praktijken_en_veiligheid&quot;&gt;Goede praktijken en veiligheid&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_basisbeveiliging&quot;&gt;basisbeveiliging&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Configurer fail2ban pour protéger contre les attaques par force brute
sudo apt update &amp;amp;&amp;amp; sudo apt install fail2ban

# Limiter l&#39;accès avec UFW (exemple : autoriser seulement certaines IP)
sudo ufw allow from 203.0.113.0/24 to any port 8080&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_monitoring_van_verbindingen&quot;&gt;Monitoring van verbindingen&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Surveiller les connexions en temps réel
sudo netstat -an | grep :8080

# Logs des connexions (selon votre application)
sudo tail -f /var/log/nginx/access.log  # pour Nginx
sudo journalctl -f -u your-service      # pour un service systemd&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_gebruik_van_een_reverse_proxy&quot;&gt;Gebruik van een reverse proxy&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Voor betere veiligheid en flexibiliteit, overweeg het gebruik van een reverse proxy zoals Nginx :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-nginx hljs&quot; data-lang=&quot;nginx&quot;&gt;server {
    listen 80;
    server_name votre-domaine.com;

    location / {
        proxy_pass http://localhost:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_alternatieven_voor_poortforwarding&quot;&gt;Alternatieven voor poortforwarding&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_cloudoplossingen&quot;&gt;cloudoplossingen&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ngrok&lt;/strong&gt;: tijdelijk veilige tunnel&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Cloudflare Tunnel&lt;/strong&gt;gratis en veilige oplossing&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;serveo.net&lt;/strong&gt;: simpele SSH-tunnel&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Exemple avec ngrok
ngrok http 8080

# Exemple avec serveo
ssh -R 80:localhost:8080 serveo.net&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_vps_en_reverse_proxy&quot;&gt;VPS en reverse proxy&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Voor professioneel gebruik, overweeg het gebruik van een VPS met een reverse proxy dat via VPN naar uw lokale infrastructuur wijst.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_probleemoplossing&quot;&gt;Probleemoplossing&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_algemene_problemen&quot;&gt;Algemene problemen&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;col style=&quot;width: 60%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Probleem&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Oplossing&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Service niet toegankelijk vanaf buiten&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Controleer de configuratie van de poortdoorsturing en dat de service luistert op 0.0.0.0&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Verbinding geweigerd&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;De service is niet gestart of luistert alleen op 127.0.0.1&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Verbindingstimeout&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Firewallprobleem (box of Ubuntu) of verkeerd geconfigureerde port forwarding&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Openbare IP verandert regelmatig&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Configureer een dynamische DNS (DynDNS, No-IP, enz.)&lt;/p&gt;&lt;/td&gt;
