        &amp;lt;label for=&quot;human&quot;&amp;gt;Humain&amp;lt;/label&amp;gt;

        &amp;lt;input type=&quot;radio&quot; name=&quot;type&quot; id=&quot;dog&quot; /&amp;gt;
