&lt;h2 id=&quot;toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Inleiding JavaScript&lt;/span&gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#start&quot;&gt;Variabelen, rekenkundige operatoren en tekstreeksen&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
