&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Inleiding JavaScript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
