&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#sysProp&quot;&gt;System.Eigenschappen&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#threads&quot;&gt;Draden&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#regex&quot;&gt;Reguliere expressies&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
